import { stdout } from std.io;
class NetworkError implements Throwable {
    inmut reason: String;
    construct(reason: String) { this.reason = reason; }
    message(): String { return this.reason; }
    code(): String { return "NETWORK"; }
    cause(): Error? { return null; }
    stack_trace(): StackTrace { return StackTrace(); }
}
fn risky(): Int32 throws NetworkError {
    throw NetworkError("connection lost");
}
fn main(): Void {
    try {
        mut v: Int32 = risky();
        stdout.println(v);
    } catch NetworkError(e) {
        stdout.println(e.message());
    }
}
